	csrr t0, sepc
	SREG t0, 0(x2)          # store sepc to signature
	addi x2, x2, SIG_STRIDE
	csrr t0, stval
	SREG t0, 0(x2)          # store stval to signature
	addi x2, x2, SIG_STRIDE
