	andi t0, t0, 3
	xori t0, t0, 3          # t0=0 iff bits[1:0]==0b11 (uncompressed)
	beqz t0, s_uncompressed
s_compressed:
	csrr t0, sepc
	addi t0, t0, 2          # 16-bit instruction: advance sepc by 2
	j    s_done
s_uncompressed:
	csrr t0, sepc
	addi t0, t0, 4          # 32-bit instruction: advance sepc by 4
s_done:
	csrw sepc, t0
	sret

sothertrap:
